def centered_stars(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")
    return [' ' * (n - i - 1) + '*' * (2 * i + 1) for i in range(n)]

assert centered_stars(1) == ['*']
assert centered_stars(3) == ['  *', ' ***', '*****']
try:
    centered_stars(0)
    assert False
except ValueError:
    pass

if __name__ == '__main__':
    for row in centered_stars(5):
        print(row)
```

